  "Sends to your inbox": { es: "Llega a tu bandeja de entrada", ar: "يُرسل إلى بريدك الوارد", zh: "发送到你的收件箱", sw: "Hutuma kwenye kikasha chako", sv: "Skickas till din inkorg", de: "Sendet in dein Postfach", pt: "Envia para sua caixa de entrada", fr: "Envoie dans votre boîte" },
  "Call to action": { es: "Llamada a la acción", ar: "دعوة إلى اتخاذ إجراء", zh: "行动号召", sw: "Wito wa kuchukua hatua", sv: "Uppmaning", de: "Handlungsaufforderung", pt: "Chamada para ação", fr: "Appel à l'action" },
  "Bold band with one button": { es: "Franja llamativa con un botón", ar: "شريط بارز بزر واحد", zh: "醒目的横幅配一个按钮", sw: "Utepe unaovutia wenye kitufe kimoja", sv: "Iögonfallande band med en knapp", de: "Auffälliges Band mit einem Knopf", pt: "Faixa chamativa com um botão", fr: "Bandeau voyant avec un bouton" },
