  "Stripe Payment Link (optional)": { es: "Enlace de pago de Stripe (opcional)", ar: "رابط دفع Stripe (اختياري)", zh: "Stripe 付款链接（可选）", sw: "Kiungo cha Malipo cha Stripe (si lazima)", sv: "Stripe-betallänk (valfritt)", de: "Stripe-Zahlungslink (optional)", pt: "Link de pagamento do Stripe (opcional)", fr: "Lien de paiement Stripe (facultatif)" },
